WITH with_windows AS (SELECT *, LEAD(humidity) OVER (PARTITION BY device_code ORDER BY status_bits, id) AS next_humidity, LAG(temp_c) OVER (PARTITION BY device_code ORDER BY status_bits, id) AS prev_temp_c, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY status_bits, id) AS row_seq, COUNT(pressure) OVER (PARTITION BY device_code) AS device_code_count_pressure FROM device_readings WHERE status_bits BETWEEN 3 AND 6) SELECT device_code, CASE WHEN temp_c >= 41.6 THEN 'LARGE' ELSE 'SMALL' END AS temp_c_tier, MAX(reading_ts) AS last_reading_ts, CORR(humidity, pressure) AS corr_humidity_pressure, MIN(status_bits) AS min_status_bits FROM with_windows GROUP BY GROUPING SETS ((device_code, CASE WHEN temp_c >= 41.6 THEN 'LARGE' ELSE 'SMALL' END), (device_code), ()) ORDER BY device_code;
